import type { Tx } from '@nmp/db'
import { z } from 'zod'
import { recordAudit } from '../../lib/audit.js'
import { ApiError, notFound } from '../../lib/errors.js'
import type { Envelope } from '../../lib/http.js'
import { decodeCursor, toPage } from '../../lib/pagination.js'
import { invalidField } from './market-validation.js'
import { pgCode } from './pg.js'
import { inScope } from './scope.js'
import { recordStructureChange } from './structure.js'

/** At most this many periods are generated by one request (422 GENERATION_LIMIT). */
export const GENERATION_LIMIT = 520

export interface CalendarView {
  id: string
  market: { id: string; code: string }
  name: string
  cadence: 'weekly' | 'monthly'
  cutoff_time_zone: string
  first_period_start: string
  periods: { count: number; first_starts_at: Date | null; last_ends_at: Date | null; open: number }
}

interface CalendarRow {
  id: string
  market_id: string
  code: string
  name: string
  cadence: 'weekly' | 'monthly'
  cutoff_time_zone: string
  first_period_start: string
  count: number
  first_starts_at: Date | null
  last_ends_at: Date | null
  open: number
}

const CALENDAR_SELECT = `
  SELECT c.id, c.market_id, m.code, c.name, c.cadence, c.cutoff_time_zone,
         to_char(c.first_period_start, 'YYYY-MM-DD') AS first_period_start, count(p.id)::int AS count,
         min(p.starts_at) AS first_starts_at, max(p.ends_at) AS last_ends_at,
         (count(p.id) FILTER (WHERE p.state = 'open'))::int AS open
  FROM calendar c JOIN market m ON m.id = c.market_id LEFT JOIN period p ON p.calendar_id = c.id`

const toView = (row: CalendarRow): CalendarView => ({
  id: row.id, market: { id: row.market_id, code: row.code }, name: row.name, cadence: row.cadence,
  cutoff_time_zone: row.cutoff_time_zone, first_period_start: row.first_period_start,
  periods: { count: row.count, first_starts_at: row.first_starts_at, last_ends_at: row.last_ends_at, open: row.open },
})

export async function listCalendars(tx: Tx, scope: readonly string[] | null, marketId: string | undefined): Promise<CalendarView[]> {
  const { rows } = await tx.query<CalendarRow>(
    `${CALENDAR_SELECT} WHERE ($1::uuid[] IS NULL OR c.market_id = ANY ($1)) AND ($2::uuid IS NULL OR c.market_id = $2)
     GROUP BY c.id, m.code ORDER BY m.code, c.name`,
    [scope, marketId ?? null],
  )
  return rows.map(toView)
}

async function calendarView(tx: Tx, id: string): Promise<CalendarView> {
  const { rows } = await tx.query<CalendarRow>(`${CALENDAR_SELECT} WHERE c.id = $1 GROUP BY c.id, m.code`, [id])
  return toView(rows[0]!)
}

/** The calendar (locked) when it exists and its market is in scope; 404 otherwise. */
async function lockCalendar(tx: Tx, id: string, scope: readonly string[] | null): Promise<{ id: string; market_id: string; name: string }> {
  const { rows } = await tx.query<{ id: string; market_id: string; name: string }>('SELECT id, market_id, name FROM calendar WHERE id = $1 FOR UPDATE', [id])
  const calendar = rows[0]
  if (calendar === undefined || !inScope(scope, calendar.market_id)) throw notFound()
  return calendar
}

// Local period starts not yet generated, from the day after the last generated period's local start (or the first
// period start) while before $3 (local, exclusive): either the given date + 1 day, or periods_ahead periods past the
// later of the first period start and today in the cut-off zone (BR-PER-01). Monthly periods start on day 1 local
// midnight, weekly ones on the weekday of the first period start.
const SERIES = `
  WITH c AS (
    SELECT id, cutoff_time_zone AS tz, first_period_start AS first,
           CASE cadence WHEN 'monthly' THEN interval '1 month' ELSE interval '7 days' END AS step
    FROM calendar WHERE id = $1),
  bounds AS (
    SELECT c.*,
           coalesce((SELECT max(p.starts_at) AT TIME ZONE c.tz FROM period p WHERE p.calendar_id = c.id) + c.step,
                    c.first::timestamp) AS from_local,
           coalesce(($3::date + 1)::timestamp, greatest(c.first, (now() AT TIME ZONE c.tz)::date) + $2::int * c.step) AS until_local
    FROM c),
  series AS (
    SELECT b.tz, b.step, d FROM bounds b, generate_series(b.from_local, b.until_local - interval '1 day', b.step) AS d)`

export type Horizon = { readonly periodsAhead: number } | { readonly through: string }

/** Generates the calendar's open periods up to the horizon (idempotent: existing periods are kept). */
async function generatePeriods(tx: Tx, calendarId: string, horizon: Horizon): Promise<number> {
  const params = 'periodsAhead' in horizon ? [calendarId, horizon.periodsAhead, null] : [calendarId, null, horizon.through]
  const { rows } = await tx.query<{ count: number }>(`${SERIES} SELECT count(*)::int AS count FROM series`, params)
  const count = rows[0]!.count
  if (count > GENERATION_LIMIT) {
    throw new ApiError(422, 'GENERATION_LIMIT', `One request generates at most ${GENERATION_LIMIT} periods.`, { requested: count, limit: GENERATION_LIMIT })
  }
  const inserted = await tx.query(
    `${SERIES}
     INSERT INTO period (tenant_id, calendar_id, starts_at, ends_at)
     SELECT app_tenant_id(), $1, d AT TIME ZONE tz, (d + step) AT TIME ZONE tz FROM series
     ON CONFLICT DO NOTHING`,
    params,
  )
  return inserted.rowCount ?? 0
}

export interface NewCalendar {
  readonly market_id: string
  readonly name: string
  readonly cadence: 'weekly' | 'monthly'
  readonly cutoff_time_zone: string
  readonly first_period_start: string
  readonly periods_ahead: number
  readonly reason: string
}

async function assertKnownZone(tx: Tx, zone: string): Promise<void> {
  const { rows } = await tx.query<{ known: boolean }>('SELECT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = $1) AS known', [zone])
  if (!rows[0]!.known) throw invalidField('cutoff_time_zone', 'not an IANA time zone')
}

/** AC-TEN2-4: a calendar of a market in scope and its open periods through periods_ahead periods after now. */
export async function createCalendar(tx: Tx, scope: readonly string[] | null, input: NewCalendar): Promise<{ calendar: CalendarView; generated: number }> {
  const { rows: markets } = await tx.query('SELECT 1 FROM market WHERE id = $1', [input.market_id])
  if (markets.length === 0 || !inScope(scope, input.market_id)) throw invalidField('market_id', 'no such market')
  if (input.cadence === 'monthly' && !input.first_period_start.endsWith('-01')) {
    throw invalidField('first_period_start', 'a monthly calendar starts on the first day of a month')
  }
  await assertKnownZone(tx, input.cutoff_time_zone)
  let id: string
  try {
    const { rows } = await tx.query<{ id: string }>(
      `INSERT INTO calendar (tenant_id, market_id, name, cadence, cutoff_time_zone, first_period_start, created_by)
       VALUES (app_tenant_id(), $1, $2, $3, $4, $5, current_setting('app.user_id')::uuid) RETURNING id`,
      [input.market_id, input.name, input.cadence, input.cutoff_time_zone, input.first_period_start],
    )
    id = rows[0]!.id
  } catch (error) {
    if (pgCode(error) === '23505') throw new ApiError(409, 'CALENDAR_NAME_TAKEN', 'The market already has a calendar with this name.')
    throw error
  }
  const generated = await generatePeriods(tx, id, { periodsAhead: input.periods_ahead })
  await recordAudit(tx, {
    action: 'CALENDAR.CREATED', objectType: 'calendar', objectId: id,
    after: { market_id: input.market_id, name: input.name, cadence: input.cadence, cutoff_time_zone: input.cutoff_time_zone, generated },
    reason: input.reason,
  })
  await recordStructureChange(tx, input.reason)
  return { calendar: await calendarView(tx, id), generated }
}

export async function renameCalendar(tx: Tx, id: string, scope: readonly string[] | null, name: string, reason: string): Promise<CalendarView> {
  const calendar = await lockCalendar(tx, id, scope)
  try {
    await tx.query('UPDATE calendar SET name = $2 WHERE id = $1', [id, name])
  } catch (error) {
    if (pgCode(error) === '23505') throw new ApiError(409, 'CALENDAR_NAME_TAKEN', 'The market already has a calendar with this name.')
    throw error
  }
  await recordAudit(tx, { action: 'CALENDAR.RENAMED', objectType: 'calendar', objectId: id, before: { name: calendar.name }, after: { name }, reason })
  await recordStructureChange(tx, reason)
  return calendarView(tx, id)
}

/** D-B1-11: a calendar whose periods are all open is deleted with them; otherwise 409 PERIOD_COMMITTED. */
export async function deleteCalendar(tx: Tx, id: string, scope: readonly string[] | null, reason: string): Promise<void> {
  const calendar = await lockCalendar(tx, id, scope)
  const { rows } = await tx.query<{ closed: number }>(
    `SELECT count(*)::int AS closed FROM period WHERE calendar_id = $1 AND state <> 'open'`, // no state change through the app in B1
    [id],
  )
  if (rows[0]!.closed > 0) {
    throw new ApiError(409, 'PERIOD_COMMITTED', 'The calendar has periods past open and cannot be deleted.', { periods_not_open: rows[0]!.closed })
  }
  const deleted = await tx.query('DELETE FROM period WHERE calendar_id = $1', [id])
  await tx.query('DELETE FROM calendar WHERE id = $1', [id])
  await recordAudit(tx, {
    action: 'CALENDAR.DELETED', objectType: 'calendar', objectId: id, before: { name: calendar.name, market_id: calendar.market_id, periods: deleted.rowCount }, reason,
  })
  await recordStructureChange(tx, reason)
}

/** POST /v1/calendars/:id/periods: periods starting on or before `through` (local date). */
export async function extendPeriods(tx: Tx, id: string, scope: readonly string[] | null, through: string, reason: string): Promise<{ generated: number }> {
  await lockCalendar(tx, id, scope)
  const generated = await generatePeriods(tx, id, { through })
  await recordAudit(tx, { action: 'CALENDAR.PERIODS_GENERATED', objectType: 'calendar', objectId: id, after: { through, generated }, reason })
  await recordStructureChange(tx, reason) // D-B1-02: the structure carries each calendar's period horizon
  return { generated }
}

export interface PeriodView {
  id: string
  starts_at: Date
  ends_at: Date
  state: string
}

/** GET /v1/calendars/:id/periods: ascending by start, ?from (inclusive) &to (exclusive) on the start. */
export async function listPeriods(
  tx: Tx, id: string, scope: readonly string[] | null, query: { from?: string; to?: string; cursor?: string; limit: number },
): Promise<Envelope<PeriodView[]>> {
  const { rows: calendars } = await tx.query<{ market_id: string }>('SELECT market_id FROM calendar WHERE id = $1', [id])
  if (calendars[0] === undefined || !inScope(scope, calendars[0].market_id)) throw notFound()
  const after = decodeCursor(query.cursor, z.iso.datetime({ offset: true }))
  const { rows } = await tx.query<PeriodView>(
    `SELECT id, starts_at, ends_at, state FROM period
     WHERE calendar_id = $1 AND ($2::timestamptz IS NULL OR starts_at >= $2) AND ($3::timestamptz IS NULL OR starts_at < $3)
       AND ($4::timestamptz IS NULL OR starts_at > $4)
     ORDER BY starts_at LIMIT $5`,
    [id, query.from ?? null, query.to ?? null, after ?? null, query.limit + 1],
  )
  return toPage(rows, query.limit, (row) => row.starts_at.toISOString())
}
